using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using F=System.Windows.Forms;
namespace GearLab {
 static class PresetTransitionTests {
  static int checks;internal static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
  internal static Parameters Screenshot(){var p=Engine.Starter(0);p.MotorPreset=0;p.AutoFit=false;p.Ratio=8;p.OutputRadius=21.27;p.ModelCaseInner=30;p.ModelCaseOuter=37;p.ModelCaseBearingB=4;p.ModelInputBearingD=13;p.ModelInputBearingB=4;p.ModelGap=.15;p.ModelFlange=2;p.ModelShaftExtension=2;p.ModelRollerAxle=1;return p;}
  public static int Run(string folder){Directory.CreateDirectory(folder);var log=new StringBuilder();try{
   // This sequence failed on 1.4: 30/37 mm Micro supports survived the normal preset.
   var first=MicroPreset.Starter();Engine.SetPreset(first,2);first.Ratio=8;Check(Engine.FitOverall(first),"normal 8:1 fit");var initial=Engine.Calculate(first);initial.Model=CadBuilder.Build(initial);Check(initial.Model.Valid,"Micro -> normal NEMA 17 leaves invalid 3D: "+string.Join(";",initial.Model.Errors));
   for(int kind=0;kind<4;kind++)for(int preset=1;preset<=4;preset++){var p=MicroPreset.Starter();p.Kind=kind;p.Ratio=kind==0?20:kind==3?4:2;Engine.SetPreset(p,preset);Check(p.CycloidLayout==0&&p.ModelCaseInner==0&&p.ModelCaseOuter==0,"reset all 3D support dimensions "+kind+"/"+preset);Check(Engine.FitOverall(p),"fit "+kind+"/"+preset);var r=Engine.Calculate(p);r.Model=CadBuilder.Build(r);Check(r.Valid&&r.Model.Valid,"CAD after Micro "+kind+"/"+preset+": "+string.Join(";",r.Model.Errors));StepExport.Write(r.Model,Path.Combine(folder,"kind-"+kind+"-preset-"+preset+".step"));}
   var bad=Screenshot();var before=Engine.Calculate(bad);before.Model=CadBuilder.Build(before);Check(before.Valid&&!before.Model.Valid&&before.Model.Errors.Any(e=>e.Contains("47,54")),"screenshot geometry and 3D failure reproduced");ReleaseSupport.WriteText(Path.Combine(folder,"screenshot-before.gear.json"),ReleaseSupport.Serialize(bad),Encoding.UTF8);var saved=Engine.Clone(bad);var method=typeof(Engine).GetMethod("ResetCadSettings");Check(method!=null,"3D reset method");method.Invoke(null,new object[]{bad});foreach(var prop in typeof(Parameters).GetProperties().Where(p=>!p.Name.StartsWith("Model")&&!p.Name.StartsWith("Micro")&&p.Name!="RingBridge"))Check(object.Equals(prop.GetValue(saved,null),prop.GetValue(bad,null)),"3D reset changed working parameter "+prop.Name);var after=Engine.Calculate(bad);after.Model=CadBuilder.Build(after);Check(after.Valid&&after.Model.Valid,"3D recovery of manual screenshot: "+string.Join(";",after.Model.Errors));ReleaseSupport.WriteText(Path.Combine(folder,"screenshot-fixed.gear.json"),ReleaseSupport.Serialize(bad),Encoding.UTF8);StepExport.Write(after.Model,Path.Combine(folder,"screenshot-fixed.step"));
   using(var form=new MainForm(new TestDialogs()))form.PresetTransitionUi(folder,log);
   log.AppendLine("PASS "+checks+" checks: Micro to all 16 normal type/preset combinations, screenshot reproduced/recovered, working dimensions preserved, STEP exports.");File.WriteAllText(Path.Combine(folder,"preset-results.txt"),log.ToString(),Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"preset-error.txt"),log+Environment.NewLine+ex,Encoding.UTF8);return 1;}}
 }
 public partial class MainForm {
  internal void PresetTransitionUi(string folder,StringBuilder log){Opacity=0;ShowInTaskbar=false;Show();animation.Stop();Apply(Engine.Starter(0),true);ShowFullModel();for(int k=0;k<4;k++){preset.SelectedIndex=5;kind.SelectedIndex=k;if(k==0){preset.SelectedIndex=2;ratioButtons[8].PerformClick();}for(int index=1;index<=4;index++){preset.SelectedIndex=index;PresetTransitionTests.Check(result.Valid&&result.Model.Valid,"UI normal preset after Micro "+k+"/"+index+": "+string.Join(";",result.Model.Errors));PresetTransitionTests.Check(canvas.View==5,"UI left 3D on preset change");VisibilityTests.Ready(canvas.Viewer.Scene);PresetTransitionTests.Check(canvas.Viewer.Scene.Nodes.Count==result.Model.Parts.Count&&canvas.Viewer.Scene.Nodes.All(n=>n.Surface.Geometry!=null),"rendered full scene "+k+"/"+index);}}
   Apply(PresetTransitionTests.Screenshot(),false);PresetTransitionTests.Check(!result.Model.Valid&&banner.Text.Contains("3D")&&!step.Enabled,"manual invalid CAD stays blocked");var reset=VisibilityTests.Controls(this).OfType<F.Button>().Single(b=>b.Text=="Сбросить 3D");reset.PerformClick();PresetTransitionTests.Check(result.Model.Valid&&p.Ratio==8&&p.Radius==35&&p.OutputRadius==21.27&&!p.AutoFit&&step.Enabled,"reset UI preserves manual profile");VisibilityTests.Ready(canvas.Viewer.Scene);canvas.Viewer.Scene.SavePng(Path.Combine(folder,"screenshot-fixed.png"),900,700);cycleLayout.SelectedIndex=1;cycleLayout.SelectedIndex=0;PresetTransitionTests.Check(p.Ratio==8&&p.OutputRadius==21.27&&result.Model.Valid&&canvas.View==5,"layout cache retains repaired manual setup");var custom=MicroPreset.Starter();custom.Ratio=8;custom.MicroJournal=9;custom.BearingInner=10;custom.BallDiameter=.6;Engine.FitOverall(custom);Apply(custom,true);double eccentric=p.Eccentric,outputRadius=p.OutputRadius;reset.PerformClick();PresetTransitionTests.Check(p.Eccentric==eccentric&&p.OutputRadius==outputRadius&&p.AutoFit,"3D reset must not rerun 2D autofit");closingApproved=true;Close();log.AppendLine("PASS UI: Micro -> each normal type and preset, 3D mode retained and meshes attached, manual 3D reset, ordinary/Micro round trip.");}
 }
}
